{
  "items": [
    {
      "title": "European Values Study (EVS) 2017 – Integrated Dataset",
      "url_or_doi": "https://europeanvaluesstudy.eu/surveys/surveys-evs/evs-2017/",
      "justification": "One of the most relevant datasets for studying family life, marriage, and family values across all 36 requested countries. The EVS 2017 integrated dataset contains approximately 59,438 respondents from 36 European countries, with fieldwork conducted primarily between 2017 and 2021. It includes questions about the importance of family, marriage, divorce, children, gender roles, relationships, and attitudes toward different family structures. Particularly suitable for cross-national comparisons of family values during the late 2010s and early 2020s. Data are available through GESIS."
    },
    {
      "title": "European Values Study and World Values Survey – Joint EVS/WVS Dataset 2017–2022",
      "url_or_doi": "https://www.gesis.org/en/european-values-study/data-and-documentation",
      "justification": "A harmonized international dataset combining the European Values Study 2017 and World Values Survey Wave 7. It covers approximately 90 countries worldwide, including the requested European countries. Contains individual-level information about marriage, family importance, divorce attitudes, gender equality, parenthood, and household relationships. Particularly useful for comparing family values across Eastern Europe, Western Europe, the Balkans, and the Caucasus during 2017–2022."
    },
    {
      "title": "Integrated Values Surveys (IVS) 1981–2022",
      "url_or_doi": "https://europeanvaluesstudy.eu/surveys/evs-wvs-collaborations/integrated-values-surveys/data-and-documentation/",
      "justification": "Longitudinal cross-national survey resource combining European Values Study and World Values Survey observations through 2022. Includes data relevant to the 2010s and early 2020s for many requested countries. Variables cover attitudes toward marriage, family responsibilities, divorce, parenthood, gender roles, and social values. Suitable for investigating changes in family attitudes over time and differences between European regions."
    },
    {
      "title": "International Social Survey Programme (ISSP) 2012 – Family and Changing Gender Roles IV",
      "url_or_doi": "https://doi.org/10.4232/1.12661",
      "justification": "Highly relevant cross-national survey specifically focused on family life, marriage, and changing gender roles. Includes participating countries such as Austria, Bulgaria, Croatia, Czech Republic, Denmark, Finland, France, Germany, Great Britain, Hungary, Iceland, Latvia, Lithuania, Netherlands, Norway, Poland, Portugal, Russian Federation, Slovakia, and Slovenia. Variables address marriage attitudes, household responsibilities, childcare, women's employment, parenting, and family relationships. Fieldwork was primarily conducted between 2011 and 2015. Excellent for comparative analysis of family structures and attitudes during the 2010s."
    },
    {
      "title": "International Social Survey Programme (ISSP) 2022 – Family and Changing Gender Roles V",
      "url_or_doi": "https://doi.org/10.4232/5.ZA10000.2.0.0",
      "justification": "The fifth wave of the ISSP Family and Changing Gender Roles survey, providing more recent data on marriage, family relationships, gender roles, household labor, parenting, and attitudes toward different family arrangements. Includes participating European countries from the requested list. Particularly useful for examining family values during the 2020s and comparing them with the ISSP 2012 survey. The harmonized international dataset facilitates cross-country analysis."
    },
    {
      "title": "ISSP Family and Changing Gender Roles I–V – Cumulated Dataset",
      "url_or_doi": "https://access.gesis.org/dbk/80835",
      "justification": "A harmonized longitudinal dataset combining ISSP Family and Changing Gender Roles survey waves from 1988, 1994, 2002, 2012, and 2022. Particularly relevant because it includes both 2012 and 2022 observations, allowing comparisons across the requested decades. Contains repeated questions about marriage, family responsibilities, women's employment, household division of labor, parenting, and gender-role attitudes. Especially suitable for studying changes in European family values over time."
    },
    {
      "title": "Generations and Gender Survey (GGS) – Round I and Round II",
      "url_or_doi": "https://www.ggp-i.org/data-catalog/",
      "justification": "One of the strongest data sources for examining family formation, marriage, cohabitation, divorce, fertility, and intergenerational relationships. The Generations and Gender Survey collects detailed individual-level information about family life and life-course transitions across numerous European countries. Round II began in 2020, while earlier survey waves provide historical comparison opportunities. Particularly valuable for examining partnership histories, marriage intentions, parenthood, household composition, and family dynamics. Country and wave availability varies."
    },
    {
      "title": "Generations and Gender Programme – International Family Dynamics Data",
      "url_or_doi": "https://www.ggp-i.org/data/",
      "justification": "Provides access to cross-national longitudinal microdata on family life, partnerships, fertility, gender relations, and household transitions. The survey programme covers more than 30 countries and hundreds of thousands of respondents. Relevant European participants include several countries from the requested list, such as Austria, Czech Republic, Estonia, France, Germany, Netherlands, Norway, Poland, and others. Useful for studying changes in family formation during the 2010s and 2020s. Access and coverage differ by country."
    },
    {
      "title": "Eurostat – Marriage Indicators (demo_nind)",
      "url_or_doi": "https://doi.org/10.2908/demo_nind",
      "justification": "Official demographic dataset containing annual marriage statistics, including numbers of marriages, crude marriage rates, mean age at first marriage, and first-marriage indicators. Provides historical observations covering the 2010s and 2020s, subject to national availability. Particularly useful for comparing marriage patterns across EU countries, candidate countries, and other European countries. A strong source for quantitative analysis of marriage trends and changes associated with the COVID-19 pandemic."
    },
    {
      "title": "Eurostat – Divorce Indicators (demo_ndivind)",
      "url_or_doi": "https://doi.org/10.2908/demo_ndivind",
      "justification": "Official European statistical dataset containing annual divorce indicators, including numbers of divorces and crude divorce rates. Relevant for comparing marital dissolution patterns across European countries during the 2010s and 2020s. Can be combined with Eurostat marriage indicators to examine changes in marriage stability and divorce trends. Geographic and temporal coverage depends on reporting by national statistical authorities."
    },
    {
      "title": "Eurostat – Marriage and Divorce Statistics",
      "url_or_doi": "https://ec.europa.eu/eurostat/statistics-explained/index.php?title=Marriage_and_divorce_statistics",
      "justification": "Official Eurostat entry point for statistical datasets documenting marriage formation and dissolution across Europe. Includes marriage and divorce rates, demographic trends, and information about births inside and outside marriage. The underlying datasets provide annual observations covering the 2010s and 2020s. Particularly useful for identifying relevant Eurostat series and comparing demographic patterns across European countries."
    },
    {
      "title": "Eurostat – Distribution of Households by Household Type (ilc_lvph02)",
      "url_or_doi": "https://doi.org/10.2908/ilc_lvph02",
      "justification": "Annual dataset measuring household composition across European countries, with observations from 2003 through 2025. Includes information about different household types, such as single-person households, couples, and households with children. Covers EU member states and several non-EU European countries, including Albania, Montenegro, North Macedonia, Norway, Serbia, Switzerland, and Iceland. Particularly relevant for studying family structures, household formation, and demographic changes during the 2010s and 2020s."
    },
    {
      "title": "Eurostat – Population by Age and Marital Status, 2021 Census (cens_21m)",
      "url_or_doi": "https://doi.org/10.2908/cens_21m",
      "justification": "Official 2021 European population census dataset providing information on marital status by age and sex. Categories include never married, married or registered partnership, divorced, and widowed. Particularly useful for comparing marriage prevalence and marital-status distributions across EU countries during the 2020s. Provides detailed demographic breakdowns but does not cover every country in the requested list."
    },
    {
      "title": "Eurostat – European Union Statistics on Income and Living Conditions (EU-SILC) Microdata",
      "url_or_doi": "https://ec.europa.eu/eurostat/en/web/microdata/public-microdata/statistics-on-income-and-living-conditions",
      "justification": "Major European household survey providing annual microdata relevant to family structures, living arrangements, household income, children, and economic well-being. Includes household-level and individual-level information for EU countries and selected additional European countries. Particularly useful for studying economic aspects of marriage and family life during the 2010s and 2020s, including single-parent families, couples with children, and household living conditions. Public-use files and access conditions vary."
    },
    {
      "title": "Eurostat – Population by Household Composition and Number of Children",
      "url_or_doi": "https://ec.europa.eu/eurostat/statistics-explained/index.php?title=Household_composition_statistics",
      "justification": "Official Eurostat statistical resource identifying datasets on household composition, couples, children, and family living arrangements. Includes indicators on households with children, the number of children per household, and household structures. Relevant for investigating changes in family organization across European countries during the 2010s and 2020s. Particularly useful when combined with marriage, divorce, and fertility statistics."
    },
    {
      "title": "European Social Survey (ESS) – Cross-National Survey Data",
      "url_or_doi": "https://ess.sikt.no/",
      "justification": "Major repeated cross-national European survey covering social attitudes, demographic characteristics, and household circumstances. Survey rounds conducted throughout the 2010s and 2020s include many of the requested countries. Relevant variables include marital status, partnership status, household composition, children, gender attitudes, social relationships, and well-being. Particularly useful for examining how family circumstances relate to broader social attitudes and living conditions. Country participation differs by survey round."
    },
    {
      "title": "European Values Study 2017 – National Datasets",
      "url_or_doi": "https://access.gesis.org/dbk/65190",
      "justification": "Provides access to national-level datasets associated with the European Values Study 2017. Relevant for researchers interested in examining family values and marriage attitudes within individual countries rather than relying exclusively on the integrated dataset. Includes countries throughout Western, Northern, Central, Eastern, and Southeastern Europe, as well as the Caucasus. Particularly useful for country-specific analysis of family importance, marriage norms, divorce attitudes, and changing gender roles."
    },
    {
      "title": "European Values Study – Historical and Comparative Data Collection",
      "url_or_doi": "https://www.gesis.org/en/european-values-study/overview",
      "justification": "GESIS data collection covering multiple waves of the European Values Study, including surveys relevant to the 2010s and 2020s. The programme contains repeated questions about family, marriage, relationships, religion, work, and social values. Particularly useful for comparing family-related attitudes across the requested European countries and tracking long-term changes. Provides access to integrated and national datasets, along with documentation and questionnaires."
    },
    {
      "title": "ISSP – Family and Changing Gender Roles Survey Series",
      "url_or_doi": "https://www.gesis.org/en/issp/data-and-documentation/family-and-changing-gender-roles",
      "justification": "Official data collection for the International Social Survey Programme's specialized family and gender-role surveys. Includes the 2012 and 2022 waves, which directly match the requested decades. Contains survey questions about family organization, marriage, children, household responsibilities, women's employment, and partnership attitudes. Particularly useful for identifying participating countries, comparing survey waves, and obtaining harmonized international datasets."
    },
    {
      "title": "Eurostat – Marriage and Divorce Demographic Statistics Collection (demo_nup)",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/EN/demo_nup_esms.htm",
      "justification": "Official Eurostat metadata and dataset collection describing marriage and divorce statistics. Includes information about marriages by previous marital status, first marriage by age and sex, and divorces by marriage duration. Its geographic scope extends beyond the European Union to countries such as Albania, Armenia, Azerbaijan, Belarus, Bosnia and Herzegovina, Georgia, Montenegro, North Macedonia, Russian Federation, Serbia, and Ukraine, although data availability varies. Particularly valuable for identifying comparable administrative statistics across the full requested country list."
    },
    {
      "title": "European Values Study and World Values Survey – Integrated Values Surveys Data and Documentation",
      "url_or_doi": "https://europeanvaluesstudy.eu/surveys/evs-wvs-collaborations/integrated-values-surveys/data-and-documentation/",
      "justification": "Provides access to harmonized survey datasets and documentation for research on family values and social change across Europe. Particularly valuable for including countries that are not consistently represented in EU-focused datasets, such as Armenia, Azerbaijan, Belarus, Georgia, Russian Federation, and Ukraine. The combined surveys contain observations relevant to the 2010s and 2020s and allow investigation of marriage attitudes, family importance, divorce acceptance, parenthood, and gender norms across diverse European societies."
    }
  ]
}
